package codexus.heypixel.plugin.metadata;

import codexus.csharpsup.DotNetJson;
import com.fasterxml.jackson.databind.JsonNode;
import java.util.*;
public final class ReflectionCheckResultParser {
    private ReflectionCheckResultParser(){}
    private static final List<String> KEYWORDS=List.of("password","token","session","credential","secret","auth","key","private","uuid","hwid");
    private static final List<String> CLASSES=List.of("SessionManager","LoginManager","NetworkManager","AuthenticationService","PlayerData","UserProfile");
    public static ReflectionCheckReport parse(String json){JsonNode elements=DotNetJson.parse(json);ReflectionCheckReport report=new ReflectionCheckReport();if(elements==null||elements.isNull()||(elements.isArray()&&elements.isEmpty())){report.FinalAction="EMPTY";report.AccessPath="null";return report;}if(!elements.isArray())throw new IllegalArgumentException("Reflection check must be an array");StringBuilder access=new StringBuilder();for(int i=0;i<elements.size();i++){ReflectionCheckEntry e=parseEntry(elements.get(i));report.ChainSteps.add("Step "+(i+1)+": "+orEmpty(e.Action)+" - "+(e.ClassName==null?"from previous":e.ClassName)+"."+orEmpty(e.FieldName==null?e.EnumName:e.FieldName));if(i==elements.size()-1)report.FinalAction=e.Action;if(e.InstanceFromPrevious)report.ChainDepth++;else{access.setLength(0);access.append(orEmpty(e.ClassName));}if(e.FieldName!=null&&!e.FieldName.isEmpty())access.append('.').append(e.FieldName);else if(e.EnumName!=null&&!e.EnumName.isEmpty())access.append('.').append(e.EnumName);}report.AccessPath=access.toString();analyzeSecurity(report,elements);return report;}
    private static ReflectionCheckEntry parseEntry(JsonNode node){if(!node.isObject())throw new IllegalArgumentException("Reflection step must be an object");ReflectionCheckEntry e=new ReflectionCheckEntry();e.Action=text(node,"action");e.ClassName=text(node,"className");e.FieldName=text(node,"fieldName");e.EnumName=text(node,"enumName");JsonNode prev=node.get("instanceFromPrevious");if(prev!=null){if(prev.isTextual())e.InstanceFromPrevious="true".equals(prev.textValue());else if(prev.isBoolean())e.InstanceFromPrevious=prev.booleanValue();else throw new IllegalArgumentException("Invalid instanceFromPrevious");}return e;}
    private static String text(JsonNode node,String field){JsonNode v=node.get(field);if(v==null||v.isNull())return null;if(!v.isTextual())throw new IllegalArgumentException("Expected string: "+field);return v.textValue();}
    private static String orEmpty(String s){return s==null?"":s;}
    private static void analyzeSecurity(ReflectionCheckReport report,JsonNode elements){String lower=report.AccessPath.toLowerCase(Locale.ROOT);List<String> warnings=new ArrayList<>();for(String k:KEYWORDS)if(lower.contains(k))warnings.add("Contains danger keyword: "+k);if(report.ChainDepth>2)warnings.add("Deep chained calls (Deep: "+report.ChainDepth+")");for(JsonNode e:elements){String name=text(e,"className");if(name!=null)for(String c:CLASSES)if(name.contains(c))warnings.add("Dangerous class: "+c);}if(!lower.startsWith("com.heypixel.heypixelmod"))warnings.add("Accessing non-Heypixel classes, this is a security risk");if(!warnings.isEmpty()){report.HasSecurityRisk=true;report.SecurityWarning=String.join("; ",warnings);}}
    public static void printDiagnostics(ReflectionCheckReport report){var log=System.getLogger(ReflectionCheckResultParser.class.getName());log.log(System.Logger.Level.WARNING,"Reflect check: {0}, path: {1}, depth: {2}",report.FinalAction,report.AccessPath,report.ChainDepth);for(String step:report.ChainSteps)log.log(System.Logger.Level.WARNING,step);if(report.HasSecurityRisk)log.log(System.Logger.Level.WARNING,report.SecurityWarning);}
}
